// Types and loaders for the precomputed GPT-2 data in public/gpt2/
// (generated by scripts/export_gpt2.py).

export interface Gpt2Index {
  model: string;
  params: string;
  layers: number;
  heads: number;
  dModel: number;
  presets: { slug: string; text: string }[];
}

export interface Gpt2Prediction {
  text: string;
  p: number;
  id?: number;
}

export interface Gpt2Data {
  slug: string;
  text: string;
  /** Roman Urdu note on what to look for. */
  note: string;
  /** The same note in English. */
  noteEn: string;
  tokens: { id: number; text: string }[];
  layers: number;
  heads: number;
  /** [layer][head][query][key] attention weights (rows sum to 1, causal). */
  attentions: number[][][][];
  /** Top predictions for the token after the whole sentence. */
  nextTokens: Gpt2Prediction[];
  /** Top predictions made at each position (what GPT-2 expected next there). */
  positionTop: Gpt2Prediction[][];
  /** A query→target token pair worth inspecting and the heads that attend along it most. */
  highlight: {
    query: number;
    target: number;
    topHeads: { layer: number; head: number; weight: number }[];
  };
}

const cache = new Map<string, Promise<unknown>>();

function load<T>(path: string): Promise<T> {
  if (!cache.has(path)) {
    cache.set(
      path,
      fetch(path)
        .then((r) => {
          if (!r.ok) throw new Error(`${path}: ${r.status}`);
          return r.json();
        })
        .catch((err) => {
          cache.delete(path); // let a later attempt retry
          throw err;
        }),
    );
  }
  return cache.get(path) as Promise<T>;
}

export const loadIndex = () => load<Gpt2Index>("/gpt2/index.json");
export const loadPreset = (slug: string) => load<Gpt2Data>(`/gpt2/${slug}.json`);

/** Makes GPT-2's leading-space tokens visible: " Potter" → "·Potter". */
export function showToken(text: string): string {
  return text.replace(/^ /, "·").replace(/\n/g, "\\n");
}
